import base64
import hashlib

VERSION = "1.1.1"
SHA256 = "b2f5cd6279ef5992f6482a1702e1dd5c0ebeeaf950fde487d7556ef7a291956b"
#: Earlier pinned payloads, by SHA-256. An installation still carrying one is
#: offered an in-place update; uninstall accepts it as Control Center's own.
SUPERSEDED = {
    # v1.1.0 published a C3 idle state that freezes the board; upstream
    # withdrew it in v1.1.1.
    "0ddfef896b3ad640463eaf79ae79826d501d946eae3ce2b66f40ca5c7ee19956": "1.1.0",
}
#: The idle table ("AMD CPU") those payloads loaded, by SHA-256. Live tables
#: with one of these digests are an outdated fix, not a foreign one.
SUPERSEDED_CPU_TABLES = {
    "dcc596e8b566a74268f75d8c66bd90a23bc8ac02768283b265edfec13f9d7fca": "1.1.0",
}
PAYLOAD = ""


def archive() -> bytes:
    data = base64.b64decode(PAYLOAD, validate=True)
    if hashlib.sha256(data).hexdigest() != SHA256:
        raise ValueError("ACPI payload checksum mismatch")
    return data

